package local.skyfamily;
import android.app.*;import android.content.*;import android.graphics.*;import android.os.SystemClock;import android.view.*;import android.widget.Toast;
final class FloatingPet extends View implements SharedPreferences.OnSharedPreferenceChangeListener {
 final Activity owner;final PetState pet;final SharedPreferences settings;final Paint paint=new Paint(3);boolean foreground=false,registered=false,dragging=false;float downX,downY,startX,startY;final Runnable animation=this::animateFrame;
 FloatingPet(Activity activity,PetState state){super(activity);owner=activity;pet=state;settings=activity.getSharedPreferences("sky",0);setContentDescription("Floating virtual companion. Tap for care, drag to move.");setFocusable(true);setOnClickListener(view->care());}
 int dp(int value){return Math.round(value*getResources().getDisplayMetrics().density);}
 void foreground(boolean value){if(foreground==value)return;foreground=value;sync();}
 void sync(){removeCallbacks(animation);boolean show=settings.getBoolean("pet.dock",true);int visibility=show?VISIBLE:GONE;if(getVisibility()!=visibility)setVisibility(visibility);if(show&&foreground&&getWindowVisibility()==VISIBLE&&getWindowToken()!=null)post(animation);}
 void animateFrame(){removeCallbacks(animation);if(foreground&&isShown()&&getWindowVisibility()==VISIBLE){invalidate();postDelayed(animation,140);}}
 public void onSharedPreferenceChanged(SharedPreferences store,String key){if("pet.dock".equals(key))sync();}
 protected void onAttachedToWindow(){super.onAttachedToWindow();settings.registerOnSharedPreferenceChangeListener(this);registered=true;sync();}
 protected void onDetachedFromWindow(){removeCallbacks(animation);if(registered){settings.unregisterOnSharedPreferenceChangeListener(this);registered=false;}super.onDetachedFromWindow();}
 protected void onWindowVisibilityChanged(int visibility){super.onWindowVisibilityChanged(visibility);if(settings!=null&&animation!=null)sync();}
 void constrain(){if(!(getParent() instanceof View)||getWidth()==0||getHeight()==0)return;View parent=(View)getParent();float x=Math.max(0,Math.min(getX(),Math.max(0,parent.getWidth()-getWidth()))),y=Math.max(0,Math.min(getY(),Math.max(0,parent.getHeight()-getHeight())));if(Math.abs(x-getX())>.5f)setX(x);if(Math.abs(y-getY())>.5f)setY(y);}
 public boolean onTouchEvent(MotionEvent event){int action=event.getActionMasked();if(action==MotionEvent.ACTION_DOWN){downX=event.getRawX();downY=event.getRawY();startX=getX();startY=getY();dragging=false;return true;}if(action==MotionEvent.ACTION_MOVE){float dx=event.getRawX()-downX,dy=event.getRawY()-downY;if(Math.hypot(dx,dy)>ViewConfiguration.get(getContext()).getScaledTouchSlop())dragging=true;if(dragging){setX(startX+dx);setY(startY+dy);constrain();}return true;}if(action==MotionEvent.ACTION_UP){if(!dragging)performClick();dragging=false;return true;}if(action==MotionEvent.ACTION_CANCEL){dragging=false;return true;}return true;}
 public boolean performClick(){super.performClick();return true;}
 void care(){if(owner.isFinishing())return;String[] labels={"Feed","Play","Train","Clean","Medicine",pet.sleeping?"Wake up":"Put to sleep","Hide floating companion"};new AlertDialog.Builder(owner).setTitle("Companion / drag it to move").setItems(labels,(dialog,index)->{if(index==6){settings.edit().putBoolean("pet.dock",false).apply();return;}String[] actions={"feed","play","train","clean","medicine","sleep"};Toast.makeText(owner,pet.care(actions[index]),Toast.LENGTH_SHORT).show();invalidate();}).setNegativeButton("Close",null).show();}
 protected void onDraw(Canvas canvas){pet.tick();float scale=Math.min(getWidth()/32f,getHeight()/30f),time=SystemClock.elapsedRealtime()/1000f;canvas.save();canvas.translate((getWidth()-32*scale)/2,(getHeight()-30*scale)/2);canvas.scale(scale,scale);paint.setStyle(Paint.Style.FILL);float bounce=pet.sleeping?0:(float)Math.sin(time*3)*.8f;canvas.translate(0,bounce);paint.setColor(0xffd8d0bf);canvas.drawOval(new RectF(6,25,26,28),paint);if(pet.stage().equals("Egg")){paint.setColor(0xff93c5b2);canvas.drawOval(new RectF(9,5,23,26),paint);paint.setColor(0xff46675a);canvas.drawRect(12,12,15,15,paint);canvas.drawRect(18,18,21,21,paint);}else{int body=pet.health<30?0xffaaa4b1:pet.stage().equals("Winged companion")?0xff849bc9:0xff7ab9a5;if(pet.stage().equals("Winged companion")){paint.setColor(0xffb2bfdb);Path wing=new Path();wing.moveTo(9,13);wing.lineTo(1,7);wing.lineTo(4,21);wing.lineTo(11,20);canvas.drawPath(wing,paint);canvas.save();canvas.scale(-1,1,16,16);canvas.drawPath(wing,paint);canvas.restore();}paint.setColor(body);canvas.drawRect(7,10,25,24,paint);canvas.drawRect(10,6,22,26,paint);canvas.drawRect(8,3,13,11,paint);canvas.drawRect(19,3,24,11,paint);int step=pet.sleeping?0:((int)(time*4)%2);canvas.drawRect(8,24,13,27-step,paint);canvas.drawRect(19,24,24,26+step,paint);paint.setColor(0xff243c39);boolean blink=pet.sleeping||((int)(time*10)%43)<2;if(blink){canvas.drawRect(10,14,13,15,paint);canvas.drawRect(19,14,22,15,paint);}else{canvas.drawRect(10,12,13,16,paint);canvas.drawRect(19,12,22,16,paint);paint.setColor(0xfff8fff9);canvas.drawRect(10,12,11,13,paint);canvas.drawRect(19,12,20,13,paint);}paint.setColor(0xffae6578);canvas.drawRect(14,19,18,21,paint);}if(pet.sleeping){paint.setColor(0xff52657d);paint.setTextSize(5);canvas.drawText("Z",24,6+(float)Math.sin(time),paint);}else if(System.currentTimeMillis()<pet.reactionUntil){paint.setColor(0xffad5e78);canvas.drawCircle(26,5,2,paint);canvas.drawCircle(29,5,2,paint);Path heart=new Path();heart.moveTo(24,5);heart.lineTo(30,5);heart.lineTo(27,10);heart.close();canvas.drawPath(heart,paint);}canvas.restore();}
}
